delete from LIQUIDITY_RISK_INFO
where REG_CODE =#{regCode} AND SOLUTIONS =#{solutions} AND OCCUR_DATE =#{occurDate}
  AND REPLY_DATE =#{replyDate} AND DESCRIBED =#{described} AND DISPOSE_RESULT =#{disposeResult}
